87	impl<'r> GitAccess<'r> {
88	    /// Tries to discover a native `gix` repository at `root`; regardless of
89	    /// whether that succeeds, also prepares the `CommandRunner`-shelled
90	    /// backend against the same `root`, ready to serve as a fallback (reads)
91	    /// or as the sole backend (writes, when discovery failed).
92	    ///
93	    /// Never fails: a discovery failure just means every operation runs
94	    /// through the shell backend instead, exactly as it unconditionally
95	    /// does on `wasm32` (gix is excluded from that target's dependency set,
96	    /// so [`GitRepository::discover`] always returns `Err` there).
97	    pub fn discover(root: impl AsRef<Path>, runner: &'r dyn CommandRunner) -> Self {
98	        let root = root.as_ref();
99	        GitAccess {
100	            native: GitRepository::discover(root).ok(),
101	            shell: ShellGit::new(runner, root.to_path_buf()),
102	        }
103	    }
104	
105	    /// Re-observes the root, full commit, symbolic-HEAD state, and worktree
106	    /// through the shell backend. These facts must never come from a native
107	    /// repository handle cached before final release validation.
108	    pub fn observe_git_commit_trust(&self) -> Result<GitCommitTrustEvidence, VcsError> {
109	        self.shell.observe_git_commit_trust()
110	    }
