112	    /// Returns every staged (Git index) change relative to `base`. Shell-only:
113	    /// no native `gix` backend lists changed paths or reads blobs today.
114	    pub fn staged_changes_since(&self, base: &CommitSha) -> Result<Vec<StagedChangeV1>, VcsError> {
115	        self.shell.staged_changes_since(base)
116	    }
117	}
