214	    /// Counts invocations and answers `git tag --list` with a canned tag
215	    /// list, standing in for a real `git` binary on the shell fallback path.
216	    struct CountingTagRunner {
217	        calls: AtomicUsize,
218	        tags: Vec<String>,
219	    }
