398	    fn test_commits_since_ref_not_found_error_propagates_through_shell_fallback() {
399	        // Native is unavailable, and the shell's git log against a
400	        // nonexistent ref must surface as an Err -- proving the "no
401	        // silent unbounded walk" fix holds through the full selection
402	        // layer, not just the native backend in isolation.
403	        let ws_dir = tempfile::tempdir().unwrap();
404	        let root = ws_dir.path();
405	        assert!(GitRepository::discover(root).is_err());
406	
407	        struct FailingRefRunner;
408	        impl CommandRunner for FailingRefRunner {
409	            fn run(&self, program: &str, _args: &[&str], _cwd: &Path) -> Result<CommandOutput, CommandError> {
410	                assert_eq!(program, "git");
411	                Ok(CommandOutput {
